from pathlib import Path
import base64,json,shutil,zipfile,hashlib
out=Path('artifacts/mobile-xhs-20261103/probe');out.mkdir(parents=True,exist_ok=True)
for name in ['idle','KeyA']:shutil.copyfile('public/character/whole-piano-v3/'+name+'.jpg',out/(name+'.jpg'))
sample=Path('public/samples/piano-kw/C4.mp3').read_bytes()
(out/'index.html').write_text('''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>喵Beat音频预览检查</title><style>body{font:16px system-ui;background:#f8f4eb;color:#61412e;margin:16px}img{display:block;width:200px;height:200px;margin:auto}button{font:inherit;min-height:48px;margin:8px;padding:10px 16px}pre{white-space:pre-wrap;font:12px monospace}h1{font-size:21px}</style></head><body><h1>喵Beat · 声画预览检查</h1><p>内部验证版，非正式小工具</p><img id="cat" src="./idle.jpg" alt="完整橘猫和钢琴"><button id="ready">准备声音</button><button id="hit" disabled>点一下 C4</button><pre id="status" role="status">等待准备声音</pre><script src="./app.js"></script></body></html>''')
(out/'app.js').write_text('''(function(){'use strict';var encoded=SAMPLE;var ctx,buffer,voice,analyser,timer;var ready=document.getElementById('ready'),hit=document.getElementById('hit'),status=document.getElementById('status'),cat=document.getElementById('cat');function log(text){status.textContent+='\\n'+text;}ready.addEventListener('click',function(){try{var Constructor=window.AudioContext||window.webkitAudioContext;if(!Constructor)throw new Error('AudioContext unavailable');ctx=ctx||new Constructor();ctx.resume().then(function(){var bytes=Uint8Array.from(atob(encoded),function(c){return c.charCodeAt(0);});return new Promise(function(resolve,reject){ctx.decodeAudioData(bytes.buffer,resolve,reject);});}).then(function(value){buffer=value;hit.disabled=false;log('READY state='+ctx.state+' rate='+ctx.sampleRate+' decodedSeconds='+buffer.duration.toFixed(3));}).catch(function(error){log('FAIL '+error.message);});}catch(error){log('FAIL '+error.message);}});hit.addEventListener('click',function(){if(!buffer)return;try{voice=ctx.createBufferSource();voice.buffer=buffer;analyser=ctx.createAnalyser();voice.connect(analyser);analyser.connect(ctx.destination);voice.start();cat.src='./KeyA.jpg';var start=ctx.currentTime;log('PLAY input=C4 state='+ctx.state);clearTimeout(timer);timer=setTimeout(function(){var data=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(data);var peak=0;for(var i=0;i<data.length;i++)peak=Math.max(peak,Math.abs(data[i]-128));log('CLOCK delta='+(ctx.currentTime-start).toFixed(3)+' peak='+peak+' image='+cat.complete);cat.src='./idle.jpg';},250);}catch(error){log('FAIL '+error.message);}});document.addEventListener('visibilitychange',function(){if(document.hidden){try{if(voice)voice.stop();}catch(error){}clearTimeout(timer);cat.src='./idle.jpg';}});})();'''.replace('SAMPLE',json.dumps(base64.b64encode(sample).decode())))
(out/'NOTICES.json').write_text(json.dumps({'scope':'internal audio compatibility probe; no production acceptance','audio':{'source':'FreePats Upright Piano KW small 2019-07-03, C4','license':'CC0-1.0','licenseText':Path('public/samples/CC0-1.0.txt').read_text(),'sourceSha256':hashlib.sha256(sample).hexdigest()},'art':'Existing approved whole-scene Miao Beat orange cat frames, no composited limbs.'},ensure_ascii=False))
with zipfile.ZipFile(out.parent/'audio-probe.zip','w',zipfile.ZIP_DEFLATED)as z:
 for p in sorted(out.iterdir()):z.write(p,p.name)
print('Probe ZIP bytes:',(out.parent/'audio-probe.zip').stat().st_size)
